window.APPLICATION_PROFILES=[{"id": "kdl", "role": "AI 솔루션 운영 엔지니어", "headline": "AI 기능을 호출 가능한 서비스로 만들고, 운영 문제를 추적해 개선합니다.", "summary": "오류가 생기면 처리 단계를 나눠 원인을 좁히고, 실제 서비스에서 다시 쓸 수 있을 때까지 해결하는 데 강점이 있습니다. 인수한 문서·음성 AI 처리 코드의 모델 로딩과 한글 인식 문제를 추적해 개선했고, API와 HTTPS 배포까지 맡았습니다. 설치 후에도 발생하는 문제를 끝까지 따라가는 태도로 AI 솔루션의 안정적인 운영에 기여하겠습니다.", "order": ["document-ai", "workforce", "vision", "visitor-analytics"]}, {"id": "waion", "role": "백엔드 / Product Engineer", "headline": "사용자의 업무를 규칙과 데이터 흐름으로 정리하고 서비스로 연결합니다.", "summary": "사용자의 설명을 업무 규칙과 데이터 흐름으로 바꾸는 일을 잘합니다. 근태·채용 관리 시스템에서 계정과 조직 소속, 채용 후 직원 전환·매장 배정 같은 실제 운영 규칙을 설계하고 배포 후 변경까지 맡았습니다. 기능을 만드는 데서 끝내지 않고, 현장에서 쓰이며 생기는 문제를 확인하고 고치는 개발자로 기여하겠습니다.", "order": ["workforce", "document-ai", "visitor-analytics", "vision"]}, {"id": "medistream", "role": "EMR/CRM Product Engineer", "headline": "현장의 업무 흐름을 이해하고, 피드백을 기능과 운영 개선으로 연결합니다.", "summary": "현장에서 하던 일을 듣고, 빠진 조건을 찾아 시스템의 규칙으로 정리하는 데 강점이 있습니다. 여러 매장의 근태·채용 업무를 설계하면서 직원 관리 단위와 화면 흐름을 조정했고, 운영 중 발생한 문제도 직접 대응했습니다. 새로운 업무를 배우고 사용자 피드백을 반영해, 실제 업무가 편해지는 제품을 만들고 싶습니다.", "order": ["workforce", "visitor-analytics", "document-ai", "vision"]}, {"id": "mayi", "role": "Backend Engineer", "headline": "영상 분석 결과를 API·통계·보고서로 연결하고, 처리 병목을 개선합니다.", "summary": "느린 처리의 원인을 막연히 추측하지 않고 단계별로 확인하는 끈기가 제 강점입니다. CCTV 오토라벨링의 각 모듈을 따로 실행하며 병목을 좁혀, 다음 날까지 끝나지 않기도 하던 작업을 당시 테스트에서 1시간 이내로 줄였습니다. 영상 분석 결과를 조회 도구·보고서와 연결한 경험을 바탕으로 매장 데이터가 실제로 쓰이는 기능을 만드는 데 기여하겠습니다.", "order": ["vision", "visitor-analytics", "document-ai", "workforce"]}, {"id": "jnpmedi", "role": "AI Driven Product Engineer", "headline": "업무의 의사결정 흐름을 설계하고, AI와 협업해 실제 제품으로 연결합니다.", "summary": "모호한 업무 요구를 구체적인 규칙과 실행 가능한 구조로 바꾸고, 결과를 확인하며 끝까지 개선하는 사람입니다. 근태·채용 관리 시스템의 설계와 운영 판단을 맡고 AI를 구현 도구로 활용했으며, 실제 운영에 영향을 준 인프라 문제도 환경 분리와 자동화로 개선했습니다. AI가 만든 결과를 그대로 넘기지 않고 업무에 맞는지 판단하는 책임감을 제품 개발에 보태겠습니다.", "order": ["workforce", "document-ai", "vision", "visitor-analytics"]}, {"id": "connectwave", "role": "메이크샵 프라이빗 클라우드 엔지니어", "headline": "서비스 운영에서 드러난 자원·환경 문제를 분리와 자동화로 개선합니다.", "summary": "운영에 문제가 생기면 당장 복구하는 데서 멈추지 않고, 같은 간섭이 반복되지 않도록 구조를 바꾸려 합니다. 공유 EC2·RDS의 자원·DB 병목 문제에 대응해 환경을 분리하고, staging을 필요할 때만 운영하는 방식과 자동화 흐름을 설계했습니다. 실제 서비스의 제약과 비용을 함께 보며 운영 방식을 개선해 온 경험으로 기여하겠습니다.", "order": ["workforce", "document-ai", "vision", "visitor-analytics"]}, {"id": "miridih", "role": "미리캔버스 Product Engineer", "headline": "AI 처리 결과를 사용자가 다루는 화면·데이터·업무 도구로 만듭니다.", "summary": "처리된 데이터를 사용자가 이해하고 활용할 수 있는 도구로 만드는 데 관심이 많습니다. CCTV 분석 결과를 조회·비교 화면과 보고서로 연결했고, 업무 관리 시스템에서는 요구사항과 화면의 세부 동작을 조정하며 실제 사용 흐름을 챙겼습니다. AI를 구현에 활용하되 사용자가 겪는 불편과 결과의 완성도를 직접 확인하는 태도로 제품을 개선하겠습니다.", "order": ["visitor-analytics", "document-ai", "workforce", "vision"]}, {"id": "collabops", "role": "백엔드 Platform 엔지니어", "headline": "AI 실행 흐름과 서비스 API·배포를 연결하고 병목을 개선합니다.", "summary": "넘겨받은 코드가 잘 동작하지 않을 때 실행 흐름을 하나씩 확인하고, 원인을 좁혀 고치는 데 강점이 있습니다. 문서·음성 AI의 처리 지연과 정제 흐름을 개선하고 API·배포 환경까지 맡았으며, 영상 분석 결과를 기존 서버와 연결하는 작업도 진행했습니다. 익숙하지 않은 구조도 직접 실행하고 배우며 서비스에 필요한 형태로 정리하겠습니다.", "order": ["document-ai", "workforce", "vision", "visitor-analytics"]}, {"id": "tura", "role": "AI·커머스 업무자동화 개발자", "headline": "반복되는 업무를 데이터 흐름과 자동화 도구로 바꿉니다.", "summary": "반복되는 일을 보면 어떤 규칙과 데이터로 정리하면 줄일 수 있을지부터 생각합니다. 근태·채용 업무의 흐름을 시스템으로 구성하고, 통계 조회와 보고서 작성도 도구로 연결해 왔습니다. AI를 활용해 빠르게 시도하되 실제 업무에서 쓸 수 있는지 세부 동작을 확인하며, 운영자의 시간을 아끼는 자동화를 만들겠습니다.", "order": ["workforce", "visitor-analytics", "document-ai", "vision"]}];
window.RESUME_FACTS={"workforce":{"title":"근태·채용 관리 시스템 · 업무 시스템 설계·배포·운영","company":"매장 운영 시스템 프로젝트","date":"2026.02–현재 · 프리랜서","bullets":["요구사항·업무 규칙, 시스템 구조와 화면 흐름을 설계하고 Claude Code를 활용해 구현·수정·배포·운영을 진행했습니다.","서비스 계정과 조직 소속을 구분하고 채용 확정→조직 멤버 전환→매장 배정 흐름, 스케줄·태블릿 출퇴근·직원용 웹을 구성했습니다.","staging 배포·cron 실행·CPU·메모리 부족·DB 병목 등의 운영 영향에 대응해 공유 EC2·RDS를 환경별로 분리했습니다.","GitHub Actions로 staging 기동·중지·production DB 기준 동기화를 구성하고 필요 시 운영하는 방식을 설계·적용했습니다.","production EC2를 상위 사양으로 이전하고 RDS 변경을 새벽에 예약 적용했습니다. ALB 기반 무중단 배포와 S3 버전 관리·CloudFront 제공을 적용했습니다."]},"document-ai":{"title":"문서·음성 AI 파이프라인 개선 및 API 서비스화","company":"AI 서비스 개발 프로젝트","date":"2025.06–2026.02 · 계약직","bullets":["매뉴얼·양식 관련 AI 질의응답 과제의 기존 처리 코드를 인수해 API별 실행 흐름과 데이터 정제 과정을 개선했습니다.","여러 OCR 모델의 단독·조합 적용을 테스트하고 추출 결과를 LLM으로 정제하는 흐름과 Markdown·JSON 출력을 다뤘습니다. 음성 인식 실행 설정과 일부 파라미터도 조정했습니다.","요청마다 모델을 다시 불러오던 구조와 PDF 분석·Markdown 변환의 처리 지연을 개선했습니다.","한글 인식 오류를 코드 디버깅과 자료 조사로 추적하고 관련 파일 교체로 인식 품질을 개선했습니다.","Node.js API 서버와 Nginx 리버스 프록시·Certbot HTTPS 환경 구성·배포를 단독 담당했습니다."]},"vision":{"title":"CCTV 오토라벨링 성능 개선·실시간 분석 연계","company":"AI 서비스 개발 프로젝트","date":"2025.06–2026.02 · 계약직","bullets":["군중 인식 모델의 점 좌표·밀도 맵을 활용한 박스 후보 생성·조정과 YOLO 사람 여부 검증 흐름을 개선했습니다.","영상 추출·점 좌표·박스 생성 모듈을 개별 실행하고 단계별 디버깅으로 병목을 추적했습니다. Claude 웹으로 대안을 검토하고 탐색 구조를 변경했습니다.","다음 날까지 완료되지 않기도 하던 작업을 당시 테스트에서 1시간 이내에 완료하도록 개선했습니다.","H100에서 모델별 분석 프로세스를 실행하고 RTSP 군중 분석 결과를 Kafka·Redis와 연계해 프로그램 서버로 전달했습니다.","쓰러짐·화재·싸움 관련 데이터를 수집·보완하고 모델 학습과 선별 영상 기반 시연을 진행했습니다."]},"visitor-analytics":{"title":"CCTV 방문객 통계·조회 도구·AI 보고서","company":"AI 서비스 개발 프로젝트 경력 중 개별 수행 사례","date":"약 1개월","bullets":["YOLO로 사람을 탐지하고 별도 모델로 성별·나이대를 추정한 결과를 Python에서 조합해 통계를 생성했습니다. WinForms 뷰어의 CCTV별·시간대별 조회·비교를 구현했습니다.","통계 기반 HTML 보고서와 ChatGPT API를 연동한 분석 문구 생성 기능을 구성했습니다.","영상 분석 결과를 사용자가 조회·비교·보고서 작성에 활용할 수 있는 흐름으로 연결했습니다."]}};
